'use strict';
const NAV=[['home','🏠','Home','Dashboard'],['translate','🌐','Languages','Translation and phrasebook'],['trade','📦','Trade','Products and suppliers'],['calculator','🧮','Calculator','Landed costs and margins'],['travel','🔎','Aiva Search','Flights, hotels, transport and maps'],['finance','💱','Finance','Currency and payments'],['emergency','🆘','Emergency','Travel safety'],['settings','⚙️','Settings','Local data and backups']];
const LANG=[['auto','Detect language'],['en','English'],['ckb','Kurdish Sorani'],['ar','Arabic'],['tr','Turkish'],['fa','Persian'],['fr','French'],['de','German'],['es','Spanish'],['it','Italian'],['zh-CN','Chinese Mandarin'],['pt','Portuguese'],['ru','Russian'],['ja','Japanese'],['hi','Hindi']];
const PHR=[['Hello','سڵاو','مرحباً','Merhaba'],['Thank you','سوپاس','شكراً','Teşekkür ederim'],['How much does it cost?','نرخی چەندە؟','كم السعر؟','Fiyatı ne kadar?'],['Where is the hotel?','هوتێلەکە لە کوێیە؟','أين الفندق؟','Otel nerede?'],['I need help','پێویستم بە یارمەتییە','أحتاج مساعدة','Yardıma ihtiyacım var'],['Do you speak English?','ئینگلیزی دەزانیت؟','هل تتكلم الإنجليزية؟','İngilizce biliyor musunuz?'],['I would like a quotation','دەمەوێت نرخنامەیەکم پێ بدەن','أريد عرض سعر','Fiyat teklifi istiyorum'],['What is the minimum order quantity?','کەمترین بڕی داواکردن چەندە؟','ما الحد الأدنى لكمية الطلب؟','Minimum sipariş miktarı nedir?'],['Please send the catalogue','تکایە کاتەلۆگەکە بنێرە','يرجى إرسال الكتالوج','Lütfen kataloğu gönderin'],['Where is the nearest station?','نزیکترین وێستگە لە کوێیە؟','أين أقرب محطة؟','En yakın istasyon nerede?']];
const $=id=>document.getElementById(id);
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const safeLoad=(key)=>{try{const d=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(d)?d:[]}catch{return []}};
let products=safeLoad('aiva-products-v1'),suppliers=safeLoad('aiva-suppliers-v1');
const save=()=>{localStorage.setItem('aiva-products-v1',JSON.stringify(products));localStorage.setItem('aiva-suppliers-v1',JSON.stringify(suppliers));updateStats()};
function go(id){if(!NAV.some(n=>n[0]===id))id='home';document.querySelectorAll('.panel').forEach(p=>p.classList.toggle('active',p.id===id));document.querySelectorAll('.nav,.bottom-nav button').forEach(el=>el.classList.toggle('active',el.dataset.go===id));const n=NAV.find(n=>n[0]===id);$('pageTitle').textContent=id==='home'?'Your pocket workspace':n[2];$('pageSubtitle').textContent=id==='home'?'Everything important, in one place.':n[3];history.replaceState(null,'','#'+id);window.scrollTo(0,0);if(id==='home')updateStats();}
function setupNav(){const nav=(n,cls)=>`<button type="button" class="${cls}" data-go="${n[0]}"><span class="emoji">${n[1]}</span>${n[2]}</button>`;$('sideNav').innerHTML=NAV.map(n=>nav(n,'nav')).join('');$('bottomNav').innerHTML=NAV.filter(n=>['home','travel','translate','trade','calculator','settings'].includes(n[0])).map(n=>`<button type="button" data-go="${n[0]}"><span>${n[1]}</span>${n[2]}</button>`).join('');$('homeTiles').innerHTML=NAV.filter(n=>!['home','settings'].includes(n[0])).map(n=>`<button class="tile" data-go="${n[0]}"><div class="tile-icon">${n[1]}</div><div><b>${n[2]}</b><span>${n[3]}</span></div></button>`).join('');document.addEventListener('click',e=>{const el=e.target.closest('[data-go]');if(el)go(el.dataset.go)});go(location.hash.slice(1)||'home')}
function updateStats(){$('statProducts').textContent=products.length;$('statSuppliers').textContent=suppliers.length;$('statReady').textContent=products.filter(p=>p.status==='Ready to buy').length}
function renderProducts(){const market=$('filterMarket').value,status=$('filterStatus').value;const filtered=products.filter(p=>(market==='All markets'||p.market===market)&&(status==='All statuses'||p.status===status));$('products').innerHTML=!filtered.length?'<div class="empty">No matching products yet. Add your first product to start tracking.</div>':filtered.map(p=>`<div class="item"><div class="row"><div><div class="item-title">${escapeHTML(p.name)}</div><div class="mini">${escapeHTML(p.category)} · ${escapeHTML(p.market)}</div></div><span class="tag">${escapeHTML(p.status)}</span></div><div class="mini" style="margin-top:7px">${escapeHTML([p.supplier,p.price].filter(Boolean).join(' · ')||'Supplier and quote not set')}</div><div class="actions" style="margin-top:9px"><button class="btn light" data-product-status="${escapeHTML(p.id)}">Change status</button><button class="btn ghost danger" data-product-delete="${escapeHTML(p.id)}">Delete</button></div></div>`).join('')}
function renderSuppliers(){$('suppliers').innerHTML=!suppliers.length?'<div class="empty">No suppliers saved yet.</div>':suppliers.map(s=>`<div class="item"><div class="row"><div><div class="item-title">${escapeHTML(s.name)}</div><div class="mini">${escapeHTML([s.focus,s.location,s.contact].filter(Boolean).join(' · '))}</div></div><button class="btn ghost danger" data-supplier-delete="${escapeHTML(s.id)}">Delete</button></div></div>`).join('')}
function setupTrade(){const statuses=['Researching','Contacted','Quotation received','Sample ordered','Factory visit needed','QC needed','Ready to buy','Rejected'];$('toggleProduct').onclick=()=>{$('productForm').hidden=!$('productForm').hidden};$('cancelProduct').onclick=()=>{$('productForm').hidden=true};$('productForm').addEventListener('submit',e=>{e.preventDefault();const name=$('pName').value.trim();if(!name)return;products.unshift({id:String(Date.now())+Math.random().toString(36).slice(2),name,market:$('pMarket').value,category:$('pCategory').value,status:$('pStatus').value,supplier:$('pSupplier').value.trim(),price:$('pPrice').value.trim()});save();e.target.reset();e.target.hidden=true;renderProducts()});$('supplierForm').addEventListener('submit',e=>{e.preventDefault();const name=$('sName').value.trim();if(!name)return;suppliers.unshift({id:String(Date.now())+Math.random().toString(36).slice(2),name,contact:$('sContact').value.trim(),focus:$('sFocus').value.trim(),location:$('sLocation').value.trim()});save();e.target.reset();renderSuppliers()});$('filterMarket').onchange=renderProducts;$('filterStatus').onchange=renderProducts;$('products').addEventListener('click',e=>{const del=e.target.closest('[data-product-delete]'),status=e.target.closest('[data-product-status]');if(del&&confirm('Delete this product?')){products=products.filter(p=>p.id!==del.dataset.productDelete);save();renderProducts()}else if(status){const p=products.find(p=>p.id===status.dataset.productStatus);if(p){p.status=statuses[(statuses.indexOf(p.status)+1)%statuses.length];save();renderProducts()}}});$('suppliers').addEventListener('click',e=>{const del=e.target.closest('[data-supplier-delete]');if(del&&confirm('Delete this supplier?')){suppliers=suppliers.filter(s=>s.id!==del.dataset.supplierDelete);save();renderSuppliers()}});renderProducts();renderSuppliers()}
const SPEECH_LANG={en:'en-GB',ckb:'ckb-IQ',ar:'ar-SA',tr:'tr-TR',fa:'fa-IR',fr:'fr-FR',de:'de-DE',es:'es-ES',it:'it-IT','zh-CN':'zh-CN',pt:'pt-PT',ru:'ru-RU',ja:'ja-JP',hi:'hi-IN'};
const speechLang=code=>SPEECH_LANG[code]||navigator.language||'en-GB';
const langName=code=>(LANG.find(l=>l[0]===code)||[code,code])[1];
function setStatus(kind,msg){const el=$('voiceStatus');if(!msg){el.hidden=true;el.className='voice-status';el.textContent='';return}el.hidden=false;el.className='voice-status '+kind;el.innerHTML='<span class="dot" aria-hidden="true"></span><span></span>';el.lastChild.textContent=msg}
let translateSeq=0,translateCtl=null,lastTranslation=null;
function showTranslation(text,lang,source){const out=$('translationOutput');lastTranslation=text==null?null:{text,lang,source};out.textContent=text==null?'Your translation will appear here.':text;out.classList.toggle('placeholder',text==null);out.lang=lang||'';$('listenTranslation').disabled=$('copyTranslation').disabled=text==null}
async function translateText(){const text=$('sourceText').value.trim(),source=$('langFrom').value,target=$('langTo').value;if(!text){setStatus('error','Enter or speak some text to translate.');return}if(voice.state!=='idle')stopListening();const seq=++translateSeq;translateCtl?.abort();const ctl=translateCtl=new AbortController();let timedOut=false;const timer=setTimeout(()=>{timedOut=true;ctl.abort()},20000);const btn=$('openTranslate');btn.disabled=true;btn.textContent='⏳ Translating…';setStatus('busy',`Translating into ${langName(target)}…`);try{if(navigator.onLine===false)throw Object.assign(new Error('offline'),{offline:true});const res=await fetch('/api/hub-translate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text,source,target}),signal:ctl.signal});let data={};try{data=await res.json()}catch{}if(!res.ok||typeof data.translation!=='string')throw Object.assign(new Error(data.error||'Translation failed. Please try again.'),{server:true});if(seq!==translateSeq)return;showTranslation(data.translation,target,text);const from=source==='auto'&&data.detected&&data.detected!=='auto'?langName(data.detected):langName(source);setStatus('ok',`Translated from ${from} into ${langName(target)}.`)}catch(err){if(seq!==translateSeq)return;setStatus('error',timedOut?'Translation is taking too long. Check your internet connection and tap Translate to try again.':err.server?err.message+' Tap Translate to try again.':'Network error: Aiva could not reach the translation service. Check your internet connection and tap Translate to try again.')}finally{clearTimeout(timer);if(seq===translateSeq){btn.disabled=false;btn.textContent='🌍 Translate'}}}
const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;
const voice={rec:null,state:'idle',id:0,base:'',finalText:'',interim:'',written:'',error:null,cancelled:false,stopTimer:null,maxTimer:null};
function setVoiceState(s){voice.state=s;const b=$('speakInput'),on=s!=='idle';b.classList.toggle('recording',on);b.setAttribute('aria-pressed',String(on));b.textContent=s==='idle'?'🎙️ Speak':s==='stopping'?'⏳ Finishing…':'⏹ Stop';b.disabled=s==='stopping'}
function voiceError(code){const lang=langName($('langFrom').value);return({'not-allowed':'Microphone access is blocked. Allow microphone access for Aiva in your browser settings (iPhone: Settings › Safari › Microphone), then tap Speak again. You can still type your text.','service-not-allowed':'Speech recognition is turned off or not allowed here. On iPhone, turn on Siri & Dictation (Settings › Siri) or open Aiva in Safari, then try again. You can still type, or use the microphone key on your keyboard.','no-speech':'No speech was detected. Tap Speak and talk clearly, or type your text.','audio-capture':'No microphone is available. It may be in use by another app. Close other apps using the microphone and tap Speak again.','network':'Voice recognition needs an internet connection. Check your connection and tap Speak again. Typing still works.','language-not-supported':`Voice input for ${lang} is not available on this device. Choose another "From" language, or type your text.`,'start-failed':'The microphone could not start. Wait a moment and tap Speak again, or type your text.'})[code]||'Voice input stopped unexpectedly. Tap Speak to try again, or type your text.'}
function startListening(){if(!Recognition){setStatus('error','Voice input is not supported in this browser. Type your text instead, or use the microphone key on your phone keyboard.');return}if(voice.state!=='idle')return;try{window.speechSynthesis?.cancel()}catch{}const id=++voice.id,rec=new Recognition(),live=()=>id===voice.id&&voice.rec===rec;voice.rec=rec;voice.base=$('sourceText').value.trim();voice.finalText=voice.interim='';voice.written=$('sourceText').value;voice.error=null;voice.cancelled=false;rec.lang=speechLang($('langFrom').value);rec.continuous=false;rec.interimResults=true;rec.maxAlternatives=1;rec.onstart=()=>{if(live()&&voice.state==='starting'){setVoiceState('listening');setStatus('listening','Listening… speak now, then tap Stop.')}};rec.onresult=e=>{if(!live())return;let fin='',int='';for(let i=0;i<e.results.length;i++){const r=e.results[i];if(r.isFinal)fin+=r[0].transcript+' ';else int+=r[0].transcript+' '}voice.finalText=fin.trim();voice.interim=int.trim();if($('sourceText').value!==voice.written)return;$('sourceText').value=voice.written=[voice.base,voice.finalText,voice.interim].filter(Boolean).join(' ')};rec.onerror=e=>{if(live())voice.error=e.error||'unknown'};rec.onend=()=>{if(live())finishListening()};setVoiceState('starting');setStatus('listening','Starting microphone…');voice.maxTimer=setTimeout(()=>{if(live())stopListening()},30000);try{rec.start()}catch(err){voice.error=err?.name==='NotAllowedError'?'not-allowed':'start-failed';finishListening()}}
function stopListening(){if(voice.state==='idle'||voice.state==='stopping')return;const rec=voice.rec;setVoiceState('stopping');setStatus('busy','Finishing recording…');try{rec.stop()}catch{}clearTimeout(voice.stopTimer);voice.stopTimer=setTimeout(()=>{if(voice.rec===rec)finishListening()},2500)}
function finishListening(){const rec=voice.rec;clearTimeout(voice.stopTimer);clearTimeout(voice.maxTimer);voice.rec=null;voice.id++;if(rec){rec.onstart=rec.onresult=rec.onerror=rec.onend=null;try{rec.abort()}catch{}}setVoiceState('idle');const edited=$('sourceText').value!==voice.written,heard=edited?$('sourceText').value.trim():[voice.finalText,voice.interim].filter(Boolean).join(' ').trim();if(!edited)$('sourceText').value=[voice.base,heard].filter(Boolean).join(' ');if(voice.cancelled){setStatus('',heard?'Voice input stopped. Tap Translate when ready.':null);return}if(voice.error&&!(heard&&['no-speech','aborted'].includes(voice.error))){setStatus('error',voiceError(voice.error==='aborted'?'no-speech':voice.error));return}if(!heard){setStatus('error',voiceError('no-speech'));return}translateText()}
function cancelListening(){if(voice.state!=='idle'){voice.cancelled=true;finishListening()}}
function speak(text,code){const synth=window.speechSynthesis;if(!synth||!window.SpeechSynthesisUtterance){setStatus('error','Read aloud is not available in this browser.');return}if(voice.state!=='idle')cancelListening();const u=new SpeechSynthesisUtterance(text);u.lang=speechLang(code);synth.cancel();synth.speak(u)}
function setupTranslation(){const opt=l=>`<option value="${l[0]}">${l[1]}</option>`;$('langFrom').innerHTML=LANG.map(opt).join('');$('langTo').innerHTML=LANG.filter(l=>l[0]!=='auto').map(opt).join('');$('langFrom').value='en';$('langTo').value='ckb';showTranslation(null);$('openTranslate').onclick=translateText;$('speakInput').onclick=()=>voice.state==='idle'?startListening():stopListening();$('readInput').onclick=()=>{const t=$('sourceText').value.trim();if(t)speak(t,$('langFrom').value==='auto'?'':$('langFrom').value)};$('listenTranslation').onclick=()=>{if(lastTranslation)speak(lastTranslation.text,lastTranslation.lang)};$('copyTranslation').onclick=async()=>{if(!lastTranslation)return;try{await navigator.clipboard.writeText(lastTranslation.text);setStatus('ok','Translation copied.')}catch{setStatus('error','Copy is not available here. Press and hold the translation to copy it.')}};$('swapLang').onclick=()=>{const from=$('langFrom').value,to=$('langTo').value;if(from==='auto'){setStatus('error','Choose a specific "From" language to swap.');return}if(voice.state!=='idle')cancelListening();$('langFrom').value=to;$('langTo').value=from;if(lastTranslation&&$('sourceText').value.trim()===lastTranslation.source){$('sourceText').value=lastTranslation.text;showTranslation(null)}if($('sourceText').value.trim())translateText()};$('langFrom').onchange=()=>{if(voice.state!=='idle')cancelListening();if(lastTranslation&&$('sourceText').value.trim())translateText()};$('langTo').onchange=()=>{if(lastTranslation&&$('sourceText').value.trim())translateText()};$('sourceText').addEventListener('keydown',e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();translateText()}});document.addEventListener('visibilitychange',()=>{if(document.hidden)cancelListening()});window.addEventListener('pagehide',cancelListening);$('phraseSearch').addEventListener('input',renderPhrases);renderPhrases()}
function renderPhrases(){const query=$('phraseSearch').value.trim().toLowerCase();const rows=PHR.filter(p=>p.some(s=>s.toLowerCase().includes(query)));$('phrases').innerHTML=rows.length?rows.map(p=>`<div class="item"><div class="item-title">${escapeHTML(p[0])}</div><div class="mini" dir="auto" style="margin-top:7px">کوردی: ${escapeHTML(p[1])}</div><div class="mini" dir="auto">العربية: ${escapeHTML(p[2])}</div><div class="mini">Türkçe: ${escapeHTML(p[3])}</div></div>`).join(''):'<div class="empty">No matching phrase in the offline starter set.</div>'}
function setupCalculator(){const ids=['cCurrency','cQty','cUnit','cShip','cDuty','cVat','cOther','cSell'];ids.forEach(id=>$(id).addEventListener('input',calc));calc()}
function calc(){const num=id=>Math.max(0,Number($(id).value)||0),qty=Math.max(1,Math.floor(num('cQty'))),goods=qty*num('cUnit'),ship=num('cShip'),duty=(goods+ship)*num('cDuty')/100,vat=(goods+ship+duty)*num('cVat')/100,other=num('cOther'),total=goods+ship+duty+vat+other,unit=total/qty,revenue=qty*num('cSell'),profit=revenue-total,margin=revenue?profit/revenue*100:0,currency=$('cCurrency').value,fmt=n=>new Intl.NumberFormat('en-GB',{style:'currency',currency,maximumFractionDigits:2}).format(n);$('calcResults').innerHTML=`<div class="row"><span>Goods</span><b>${fmt(goods)}</b></div><div class="item row"><span>Shipping</span><b>${fmt(ship)}</b></div><div class="item row"><span>Estimated customs duty</span><b>${fmt(duty)}</b></div><div class="item row"><span>Estimated import tax / VAT</span><b>${fmt(vat)}</b></div><div class="item row"><span>Other costs</span><b>${fmt(other)}</b></div><div class="item row"><strong>Total landed cost</strong><strong>${fmt(total)}</strong></div><div class="item row"><strong>Cost per unit</strong><strong>${fmt(unit)}</strong></div><div class="item row"><span>Gross revenue (before sales fees / taxes)</span><b>${fmt(revenue)}</b></div><div class="item row"><strong>Illustrative gross profit</strong><strong>${fmt(profit)}</strong></div><div class="item row"><strong>Illustrative margin</strong><strong>${margin.toFixed(1)}%</strong></div>`}
const AS={seq:0,from:null,to:null,airport:null,flight:null,hotel:null,hotels:[],transfers:null,mode:null,tab:'all',q:null,showAll:false};
const asFmtMoney=(n,c)=>{try{return new Intl.NumberFormat('en-GB',{style:'currency',currency:c||'GBP',maximumFractionDigits:0}).format(n)}catch{return `${c} ${Math.round(n)}`}};
const asDur=m=>m==null?'':m<60?`${m} min`:`${Math.floor(m/60)}h${m%60?` ${m%60}m`:''}`;
const asTime=t=>!t?'':/^\d\d:\d\d$/.test(t)?t:String(t).slice(11,16);
const asDay=t=>t?new Date(String(t).slice(0,10)+'T12:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short',timeZone:'UTC'}):'';
const asPlus=(a,b)=>{const d=Math.round((Date.parse(String(b).slice(0,10))-Date.parse(String(a).slice(0,10)))/864e5);return d>0?`<sup>+${d}</sup>`:''};
const asIso=d=>d.toISOString().slice(0,10);
function asStatus(kind,msg){const el=$('asStatus');if(!msg){el.hidden=true;return}el.hidden=false;el.className='voice-status '+kind;el.innerHTML='<span class="dot" aria-hidden="true"></span><span></span>';el.lastChild.textContent=msg}
async function asGet(path){const res=await fetch(path,{signal:AbortSignal.timeout(45000)});let data={};try{data=await res.json()}catch{}if(!res.ok)throw new Error(data.error||'Service unavailable. Please try again.');return data}
function asTabs(tab){AS.tab=tab;document.querySelectorAll('#asTabs .as-tab').forEach(b=>b.classList.toggle('active',b.dataset.asTab===tab));const show={all:['flights','trip','transfers','hotels','transport','maps'],flights:['flights','trip'],hotels:['hotels','trip'],transport:['transport','transfers'],maps:['maps'],transfers:['transfers','transport']}[tab];document.querySelectorAll('#asGrid [data-as]').forEach(c=>c.classList.toggle('as-hidden',!show.includes(c.dataset.as)));$('asGrid').classList.toggle('single',tab!=='all')}
function asCity(p){return p?(p.city||p.label||'').split(',')[0]:''}
function asMap(q){const u=new URLSearchParams(q);$('asMap').src='/api/travel/map?'+u}
function asTrip(){const f=AS.flight,h=AS.hotel,a=AS.airport,dep=$('asDepart').value,ret=$('asReturn').value;const fl=f?`${f.slices[0].from} → ${f.slices[0].to}`:AS.from&&a?`${AS.fromCode||'—'} → ${a.iata}`:'Choose a flight';const tr=a?`${a.iata} → ${h?'Hotel':'hotel'}`:'Airport → hotel';const ho=h?escapeHTML(h.name):'Choose a hotel';$('asTrip').innerHTML=`<div class="as-step ${f?'done':''}"><i>✈️</i><div><b>Flight</b><small>(${escapeHTML(fl)})</small></div></div><span aria-hidden="true">→</span><div class="as-step ${AS.transfers?'done':''}"><i>🚕</i><div><b>Airport Transfer</b><small>(${escapeHTML(tr)})</small></div></div><span aria-hidden="true">→</span><div class="as-step ${h?'done':''}"><i>🛏️</i><div><b>Hotel</b><small>(${ho}${dep?` · ${asDay(dep)}${ret?' – '+asDay(ret):''}`:''})</small></div></div>`}
function asFlightHTML(o,i){const s=o.slices[0],r=o.slices[1];const stops=s.stops?`${s.stops} stop${s.stops>1?'s':''}`:'Non-stop';return `<div class="as-flight ${AS.flight?.id===o.id?'sel':''}"><div><div class="as-air">${o.logo?`<img src="${escapeHTML(o.logo)}" alt="" loading="lazy">`:'✈️'}<span>${escapeHTML(o.airline)}</span></div>${i===0?'<span class="as-badge">Best Deal</span>':''}</div><div><div class="as-time">${asTime(s.departing)} <small>${escapeHTML(s.from)}</small> → ${asTime(s.arriving)}${asPlus(s.departing,s.arriving)} <small>${escapeHTML(s.to)}</small></div><div class="as-sub">${stops} · ${asDur(s.minutes)}${s.flights.length?' · '+escapeHTML(s.flights.join(', ')):''}</div>${r?`<div class="as-sub">Return ${asDay(r.departing)} ${asTime(r.departing)} → ${asTime(r.arriving)} · ${r.stops?r.stops+' stop':'Non-stop'} · ${asDur(r.minutes)}</div>`:''}</div><div class="as-price">${asFmtMoney(o.price,o.currency)}</div><button type="button" class="as-btn" data-as-flight="${i}">${AS.flight?.id===o.id?'Selected ✓':'Book Flight'}</button></div>`}
function asHotelHTML(h,i){const st=h.stars?'★'.repeat(Math.min(5,Math.round(h.stars))):'';const img=h.image?` style="background-image:url('${escapeHTML(h.image)}')"`:'';return `<div class="as-hotel ${AS.hotel?.id===h.id?'sel':''}"><div class="as-photo"${img}>${h.image?'':'🏨'}${i===0?'<span>Popular</span>':''}</div><div style="min-width:0"><div class="as-hname">${escapeHTML(h.name)}</div>${st?`<div class="as-stars" aria-label="${h.stars} stars">${st}</div>`:''}<div class="mini">${h.rating?`Guest rating ${h.rating}/10 · `:''}${emDist(h.distance)} from centre${h.address?' · '+escapeHTML(h.address):''}</div><div class="as-from">${h.price?`<div><span class="mini">From</span><br><b>${asFmtMoney(h.price.total,h.price.currency)}</b> <span class="mini">total stay</span><div class="mini">${escapeHTML([h.price.board,h.price.refundable?(h.price.cancelBy?'Free cancellation until '+asDay(h.price.cancelBy.slice(0,10)):'Refundable'):'Non-refundable',h.price.taxesDue?'+ '+asFmtMoney(h.price.taxesDue,h.price.currency)+' taxes paid at hotel':''].filter(Boolean).join(' · '))}</div></div>`:`<div class="mini">${h.available===false?'No rooms for these dates':'Price &amp; availability: connect live rates'}</div>`}<button type="button" class="as-btn" data-as-hotel="${i}">${AS.hotel?.id===h.id?'Selected ✓':h.price?'Book Hotel':'Select'}</button></div></div></div>`}
function asRenderHotels(){const list=AS.showAll?AS.hotels:AS.hotels.slice(0,4);$('asHotels').innerHTML=list.length?list.map(asHotelHTML).join(''):'<div class="empty">No hotels found near this destination.</div>';$('asHotelsAll').hidden=AS.hotels.length<=4;$('asHotelsAll').textContent=AS.showAll?'Show less':'View All'}
async function asLoadFlights(seq,q){const box=$('asFlights');box.innerHTML='<div class="empty">Searching live flights…</div>';if(!AS.fromCode||!AS.airport){box.innerHTML='<div class="empty">No airport with an IATA code was found for this route.</div>';return}try{const d=await asGet(`/api/travel/flights?${new URLSearchParams({from:AS.fromCode,to:AS.toCode||AS.airport.iata,depart:q.depart,...(q.ret?{return:q.ret}:{}),adults:q.pax,currency:'GBP'})}`);if(seq!==AS.seq)return;AS.offers=d.offers||[];$('asFlightsMeta').textContent=d.source||'';if(!d.configured){box.innerHTML=`<div class="notice warn"><b>Blocked:</b> live flights need a Duffel access token, which has not been added to Aiva yet. Route ${escapeHTML(AS.fromCode)} → ${escapeHTML(AS.toCode||AS.airport.iata)} (${emDist(Math.round(emGc(AS.from,AS.airport)))}). Airlines, times, stops, baggage and live prices will show here once the token is added. Hotels, transport, transfers and the map below are live.</div>`;return}box.innerHTML=(d.testMode?`<div class="notice warn"><b>Test data:</b> ${d.provider==='Nuitee'?'flight fares':'hotel rates'} come from the Nuitee sandbox key, so they are not real bookable prices until the Nuitee production key is added.</div>`:'')+(AS.offers.length?AS.offers.map(asFlightHTML).join(''):`<div class="empty">${escapeHTML(d.error||'No flights found for this route and date.')}</div>`)}catch(err){if(seq===AS.seq)box.innerHTML=`<div class="empty">${escapeHTML(err.message)}</div>`}}
function emGc(a,b){const R=6371000,r=Math.PI/180,dl=(b.lat-a.lat)*r,dn=(b.lon-a.lon)*r,h=Math.sin(dl/2)**2+Math.cos(a.lat*r)*Math.cos(b.lat*r)*Math.sin(dn/2)**2;return 2*R*Math.asin(Math.sqrt(h))}
async function asLoadHotels(seq,q){const box=$('asHotels');box.innerHTML='<div class="empty">Finding hotels…</div>';try{const d=await asGet(`/api/travel/hotels?${new URLSearchParams({lat:AS.to.lat,lon:AS.to.lon,checkin:q.depart,checkout:q.ret||asIso(new Date(Date.parse(q.depart)+864e5)),adults:q.pax,currency:'GBP'})}`);if(seq!==AS.seq)return;AS.hotels=d.hotels||[];AS.showAll=false;asRenderHotels();if(d.note)box.insertAdjacentHTML('afterbegin',`<div class="notice">${escapeHTML(d.note)}</div>`);if(d.testMode)box.insertAdjacentHTML('afterbegin',`<div class="notice warn"><b>Test data:</b> ${d.provider==='Nuitee'?'flight fares':'hotel rates'} come from the Nuitee sandbox key, so they are not real bookable prices until the Nuitee production key is added.</div>`);box.insertAdjacentHTML('beforeend',`<p class="mini em-source">${escapeHTML(d.source||'')}</p>`)}catch(err){if(seq===AS.seq)box.innerHTML=`<div class="empty">${escapeHTML(err.message)}</div>`}}
async function asLoadAirportTransport(seq){const box=$('asTransport'),a=AS.airport;if(!a)return;box.innerHTML='<div class="mini">Loading live departures at '+escapeHTML(a.name)+'…</div>';try{const d=await asGet(`/api/emergency/transport?lat=${a.lat}&lon=${a.lon}&radius=2500&cc=${encodeURIComponent(AS.to.countryCode||'')}`);if(seq!==AS.seq)return;const stops=(d.stops||[]).slice(0,4);box.innerHTML=`<div class="result-title">Stations at ${escapeHTML(a.name)} (${escapeHTML(a.iata)})</div>`+(stops.length?stops.map(s=>`<div class="item"><div class="row"><b>${escapeHTML(s.name)}</b><span class="mini">${emDist(s.distance)}</span></div><div class="em-state ${emColor(s.state)}">${escapeHTML(s.label)}</div>${(s.departures||[]).slice(0,3).map(x=>`<div class="mini">${escapeHTML(x.line)} → ${escapeHTML(x.destination)} · ${x.cancelled?'Cancelled':x.minutes?x.minutes+' min':'Due'}${x.platform?' · '+escapeHTML(x.platform):''}</div>`).join('')}</div>`).join(''):'<div class="mini">No stations or stops are listed within 2.5 km of this airport.</div>')+`<p class="mini em-source">${escapeHTML(d.source||'')}</p>`}catch(err){if(seq===AS.seq)box.innerHTML=`<div class="mini">${escapeHTML(err.message)}</div>`}}
async function asSearch(){const q={from:$('asFrom').value.trim(),to:$('asTo').value.trim(),depart:$('asDepart').value,ret:$('asReturn').value,pax:$('asPax').value};if(!q.from||!q.to)return asStatus('error','Enter where you are flying from and to.');if(!q.depart||q.depart<asIso(new Date()))return asStatus('error','Choose a departure date from today onwards.');if(q.ret&&q.ret<q.depart)return asStatus('error','Return date must be after the departure date.');localStorage.setItem('aiva-search-v1',JSON.stringify(q));const seq=++AS.seq;Object.assign(AS,{q,flight:null,hotel:null,transfers:null,offers:[],hotels:[]});$('asReview').hidden=true;asStatus('busy','Aiva Search is finding your trip…');try{const [f,t]=await Promise.all([asGet('/api/travel/place?q='+encodeURIComponent(q.from)),asGet('/api/travel/place?q='+encodeURIComponent(q.to))]);if(seq!==AS.seq)return;AS.from=f;AS.to=t;AS.fromCode=f.code||f.airports[0]?.iata||'';AS.airport=t.airports.find(a=>a.iata===t.code)||t.airports[0]||null;AS.toCode=t.code||'';const city=asCity(t);$('asFlightsTitle').textContent=`Flights to ${city}`;$('asHotelsTitle').textContent=`Hotels in ${city}`;$('asTransportTitle').textContent=`Transport in ${city}`;$('asTransfersTitle').textContent=AS.airport?`${AS.airport.iata} → hotel transfers`:'Airport → hotel transfers';$('asMapLabel').textContent=t.label;asMap({lat:t.lat,lon:t.lon});asTrip();asStatus('ok',`${asCity(f)} → ${city} · ${asDay(q.depart)}${q.ret?' – '+asDay(q.ret):''} · ${q.pax} passenger${q.pax>1?'s':''}`);$('asTransfers').innerHTML='<div class="empty">Select a hotel to compare trains, buses, taxis, car hire and walking from the airport.</div>';await Promise.all([asLoadFlights(seq,q),asLoadHotels(seq,q),asLoadAirportTransport(seq)])}catch(err){if(seq===AS.seq)asStatus('error',err.message)}}
function asSelectFlight(i){const o=AS.offers[i];if(!o)return;AS.flight=o;AS.airport=AS.to?.airports?.find(a=>a.iata===o.slices[0]?.to)||AS.airport;$('asFlights').innerHTML=AS.offers.map(asFlightHTML).join('');asTrip();asReview('flight');asStatus('ok',`Flight selected: ${o.airline} ${o.slices[0].from} → ${o.slices[0].to}. Hotels near ${asCity(AS.to)} are ready below.`);if(AS.tab!=='all')asTabs('hotels');$('asHotels').closest('.as-card').scrollIntoView({behavior:'smooth',block:'start'})}
async function asSelectHotel(i){const h=(AS.showAll?AS.hotels:AS.hotels.slice(0,4))[i];if(!h)return;AS.hotel=h;asRenderHotels();asTrip();asReview('hotel');const a=AS.airport,box=$('asTransfers');if(!a){box.innerHTML='<div class="empty">No arrival airport found for this destination.</div>';return}asMap({from:`${a.lat},${a.lon}`,to:`${h.lat},${h.lon}`});$('asMapLabel').textContent=`${a.iata} → ${h.name}`;box.innerHTML='<div class="empty">Comparing airport transfers…</div>';const seq=AS.seq,arr=AS.flight?.slices?.[0]?.arriving;const tz=AS.flight?.slices?.[0]?.arrivingTz;try{const d=await asGet(`/api/travel/transfers?${new URLSearchParams({from:`${a.lat},${a.lon}`,to:`${h.lat},${h.lon}`,...(arr?{time:arr}:{}),...(tz?{tz}:{})})}`);if(seq!==AS.seq||AS.hotel!==h)return;AS.transfers=d;asTrip();asRenderTransfers(d.modes.train.available!==false?'train':'taxi');if(AS.tab!=='all')asTabs('transfers');box.closest('.as-card').scrollIntoView({behavior:'smooth',block:'start'})}catch(err){box.innerHTML=`<div class="empty">${escapeHTML(err.message)}</div>`}}
const AS_MODES={train:['🚆','Train'],bus:['🚌','Bus'],taxi:['🚕','Taxi'],car:['🚗','Car hire'],walk:['🚶','Walking']};
function asRouteHTML(r){return `<div class="as-route-opt"><div class="row"><b>${asDur(r.minutes)}</b><span class="mini">${r.fare?asFmtMoney(r.fare.amount,r.fare.currency)+' fare · ':''}${emDist(r.distance)}</span></div>${r.steps.map(s=>`<div class="as-leg"><span>${s.kind==='train'?'🚆':s.kind==='bus'?'🚌':s.kind==='ferry'?'⛴️':'🚏'}</span><span><b>${escapeHTML(s.line)}</b>${s.headsign?' → '+escapeHTML(s.headsign):''} · ${asTime(s.departs)||'—'} ${escapeHTML(s.from)} → ${asTime(s.arrives)||'—'} ${escapeHTML(s.to)}${s.stops?` · ${s.stops} stops`:''}${s.operator?` <span class="mini">(${escapeHTML(s.operator)})</span>`:''}</span></div>`).join('')}</div>`}
function asRenderTransfers(mode){const d=AS.transfers;if(!d)return;AS.mode=mode;document.querySelectorAll('#asModes [data-as-mode]').forEach(b=>{const m=d.modes[b.dataset.asMode];b.classList.toggle('active',b.dataset.asMode===mode);b.classList.toggle('off',m.available===false)});const m=d.modes[mode],[ico,name]=AS_MODES[mode];let body='';if(mode==='train'||mode==='bus'){body=m.routes?.length?m.routes.map(asRouteHTML).join(''):m.available===false?`<div class="mini">No ${name.toLowerCase()} connection found from ${escapeHTML(AS.airport.iata)} to this hotel.</div>`:`<div class="notice">${escapeHTML(d.note||'Timetables unavailable right now.')}</div>`;if(m.places?.length)body+=`<div class="result-title">${mode==='train'?'Stations':'Bus stations'} at the airport</div>`+m.places.map(p=>`<div class="mini">• ${escapeHTML(p.name)} · ${emDist(p.distance)}${p.network?' · '+escapeHTML(p.network):''}</div>`).join('')}else if(mode==='taxi'||mode==='car'){body=m.minutes!=null?`<div class="as-route-opt"><div class="row"><b>${asDur(m.minutes)} drive</b><span class="mini">${emDist(m.distance)} by road</span></div><div class="mini">${mode==='taxi'?'Fares are set by local operators; Aiva does not show a guessed price.':'Rental prices come from the hire desk.'}</div></div>`:'<div class="mini">Road route unavailable right now.</div>';if(m.places?.length)body+=`<div class="result-title">${mode==='taxi'?'Taxi ranks':'Car hire desks'} at the airport</div>`+m.places.map(p=>`<div class="mini">• ${escapeHTML(p.name)} · ${emDist(p.distance)}${p.hours?' · '+escapeHTML(p.hours):''}</div>`).join('');else if(mode==='car')body+='<div class="mini">No car hire desks are listed at this airport.</div>'}else body=m.minutes!=null?`<div class="as-route-opt"><div class="row"><b>${asDur(m.minutes)} walk</b><span class="mini">${emDist(m.distance)}</span></div>${m.available?'':'<div class="mini">Too far to walk with luggage — choose train, bus or taxi.</div>'}</div>`:'<div class="mini">Walking route unavailable.</div>';$('asTransfers').innerHTML=`<div class="result-title">${ico} ${name}: ${escapeHTML(AS.airport.name)} → ${escapeHTML(AS.hotel.name)}</div>${body}<p class="mini em-source">${escapeHTML(d.source)}</p>`;$('asTransport').innerHTML=$('asTransport').innerHTML}
function asReview(kind){const f=AS.flight,h=AS.hotel,el=$('asReview'),q=AS.q;el.hidden=false;el.innerHTML=`<div class="row"><h3 style="margin:0">🧾 Your Aiva trip</h3><button type="button" class="as-btn ghost" data-as-close>Close</button></div>${f?`<div class="item"><b>✈️ ${escapeHTML(f.airline)}</b> · ${escapeHTML(f.slices.map(s=>`${s.from}→${s.to} ${asDay(s.departing)} ${asTime(s.departing)}`).join(' · '))} · ${q.pax} passenger${q.pax>1?'s':''} · <b>${asFmtMoney(f.price,f.currency)}</b>${f.baggage?` · ${escapeHTML(f.baggage)}`:''}${f.expires?`<div class="mini">Fare held by the airline until ${escapeHTML(new Date(f.expires).toLocaleString('en-GB'))}</div>`:''}</div>`:''}${h?`<div class="item"><b>🏨 ${escapeHTML(h.name)}</b> · ${asDay(q.depart)} – ${asDay(q.ret||asIso(new Date(Date.parse(q.depart)+864e5)))}${h.price?` · <b>${asFmtMoney(h.price.total,h.price.currency)}</b>${h.price.room?' · '+escapeHTML(h.price.room):''}`:' · price not available'}</div>`:''}${h?.price?.offerId?asBookFormHTML():''}${f?'<div class="notice warn"><b>Flight booking:</b> fares are shown live; airline ticketing inside Aiva is not switched on yet, so no flight is booked or charged.</div>':''}`}
const AS_PENDING='aiva-hotel-pending',AS_BOOKINGS='aiva-hotel-bookings';
function asJSON(k,d){try{return JSON.parse(localStorage.getItem(k)||'')??d}catch{return d}}
function asBookFormHTML(){const g=asJSON('aiva-guest',{});return `<form class="as-book" id="asBookForm" novalidate><h4 style="margin:12px 0 6px">🛏️ Book this room inside Aiva</h4><div class="as-book-grid"><label class="field">First name<input name="firstName" autocomplete="given-name" required maxlength="60" value="${escapeHTML(g.firstName||'')}"></label><label class="field">Last name<input name="lastName" autocomplete="family-name" required maxlength="60" value="${escapeHTML(g.lastName||'')}"></label><label class="field">Email<input name="email" type="email" autocomplete="email" required maxlength="254" value="${escapeHTML(g.email||'')}"></label></div><button type="submit" class="as-btn" id="asPayBtn">Check price &amp; pay securely</button><p class="mini">The room is re-checked with the hotel before payment. Payment is handled by Nuitée's secure card form; Aiva never sees your card number.</p><div id="asPayBox"></div></form>`}
function asLoadPaySDK(){return window.LiteAPIPayment?Promise.resolve():new Promise((ok,no)=>{const s=document.createElement('script');s.src='https://payment-wrapper.liteapi.travel/dist/liteAPIPayment.js?v=a1';s.onload=ok;s.onerror=()=>no(new Error('The secure payment form could not load. Check your connection and try again.'));document.head.appendChild(s)})}
async function asPost(path,body){const res=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:AbortSignal.timeout(70000)});let d={};try{d=await res.json()}catch{}if(!res.ok)throw new Error(d.error||'Booking service unavailable. Please try again.');return d}
async function asPay(form){const h=AS.hotel,q=AS.q,box=$('asPayBox'),btn=$('asPayBtn');const holder=Object.fromEntries(['firstName','lastName','email'].map(k=>[k,form.elements[k].value.trim()]));if(!holder.firstName||!holder.lastName||!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(holder.email)){box.innerHTML='<div class="notice warn">Enter the guest\'s first name, last name and a valid email.</div>';return}localStorage.setItem('aiva-guest',JSON.stringify(holder));btn.disabled=true;btn.textContent='Checking the room with the hotel…';box.innerHTML='';try{const p=await asPost('/api/travel/hotel-book',{action:'prebook',offerId:h.price.offerId});const pending={prebookId:p.prebookId,transactionId:p.transactionId,holder,hotel:{name:h.name,address:h.address||'',image:h.image||''},checkin:p.checkin,checkout:p.checkout,price:p.price,currency:p.currency,room:p.room,board:p.board,refundable:p.refundable,cancelBy:p.cancelBy,testMode:p.testMode,ts:Date.now()};const all=asJSON(AS_PENDING,{}),keep={};for(const[k,v]of Object.entries(all&&typeof all==='object'&&!Array.isArray(all)?all:{}))if(v?.ts>Date.now()-864e5)keep[k]=v;keep[p.prebookId]=pending;localStorage.setItem(AS_PENDING,JSON.stringify(keep));box.innerHTML=`${p.testMode?'<div class="notice warn"><b>Test booking:</b> Nuitée sandbox. Use test card 4242 4242 4242 4242, any future date and any CVC. No real money is taken.</div>':''}<div class="item"><b>${escapeHTML(h.name)}</b> · ${asDay(p.checkin)} – ${asDay(p.checkout)} · <b>${asFmtMoney(p.price,p.currency)}</b> total${p.room?' · '+escapeHTML(p.room):''}<div class="mini">${escapeHTML([p.board,p.refundable?(p.cancelBy?'Free cancellation until '+asDay(p.cancelBy.slice(0,10)):'Refundable'):'Non-refundable',p.taxesDue?'+ '+asFmtMoney(p.taxesDue,p.currency)+' taxes paid at hotel':''].filter(Boolean).join(' · '))}</div>${p.priceChanged||p.cancellationChanged?'<div class="notice warn">The hotel updated the price or cancellation terms since your search. The details above are the final ones.</div>':''}</div><div id="asPayForm"></div>`;await asLoadPaySDK();new LiteAPIPayment({publicKey:p.paymentEnv,appearance:{theme:'flat'},options:{business:{name:'Aiva'}},targetElement:'#asPayForm',secretKey:p.secretKey,returnUrl:`${location.origin}/?hotelPaid=1&pid=${encodeURIComponent(p.prebookId)}`}).handlePayment();btn.hidden=true}catch(err){box.innerHTML=`<div class="notice warn">${escapeHTML(err.message)}</div>`;btn.disabled=false;btn.textContent='Check price & pay securely'}}
function asBookingHTML(b){return `<div class="item"><b>✅ ${escapeHTML(b.hotel||'Hotel')}</b> · ${asDay(b.checkin)} – ${asDay(b.checkout)}${Number.isFinite(b.price)?` · <b>${asFmtMoney(b.price,b.currency)}</b>`:''}${b.testMode?' · <span class="mini">TEST booking</span>':''}<div class="mini">Booking ${escapeHTML(b.bookingId)}${b.confirmation?' · Hotel confirmation '+escapeHTML(b.confirmation):''} · ${escapeHTML(b.status||'CONFIRMED')}${b.room?' · '+escapeHTML(b.room):''}${b.refundable?(b.cancelBy?' · Free cancellation until '+asDay(b.cancelBy.slice(0,10)):' · Refundable'):' · Non-refundable'}</div></div>`}
function asRenderBookings(){const list=asJSON(AS_BOOKINGS,[]),el=$('asBookings');el.hidden=!list.length;el.innerHTML=`<h3 style="margin:0 0 8px">🧳 My hotel bookings</h3>${list.map(asBookingHTML).join('')}`}
async function asFinishBooking(){const u=new URLSearchParams(location.search);if(!u.has('hotelPaid'))return;const pid=u.get('pid')||'',all=asJSON(AS_PENDING,{}),p=all?.[pid]||null,drop=()=>{const m=asJSON(AS_PENDING,{});if(m&&typeof m==='object'){delete m[pid];localStorage.setItem(AS_PENDING,JSON.stringify(m))}};history.replaceState(null,'',location.pathname+'#travel');go('travel');const el=$('asReview');el.hidden=false;if(!p){el.innerHTML='<div class="notice warn">This payment link has expired. Check My hotel bookings below.</div>';return}const st=u.get('redirect_status');if(st&&st!=='succeeded'){el.innerHTML='<div class="notice warn">The payment was not completed, so nothing was booked. Search again to choose a room.</div>';drop();return}el.innerHTML='<div class="empty">Payment received. Confirming your room with the hotel…</div>';try{const b=await asPost('/api/travel/hotel-book',{action:'book',prebookId:p.prebookId,transactionId:p.transactionId,holder:p.holder});const rec={...b,hotel:b.hotel||p.hotel.name,checkin:b.checkin||p.checkin,checkout:b.checkout||p.checkout,price:Number.isFinite(b.price)?b.price:p.price,currency:b.currency||p.currency,room:b.room||p.room,testMode:p.testMode,booked:new Date().toISOString()};const list=asJSON(AS_BOOKINGS,[]).filter(x=>x.bookingId!==rec.bookingId);list.unshift(rec);localStorage.setItem(AS_BOOKINGS,JSON.stringify(list.slice(0,30)));drop();el.innerHTML=`<div class="row"><h3 style="margin:0">🎉 Hotel booked</h3><button type="button" class="as-btn ghost" data-as-close>Close</button></div>${asBookingHTML(rec)}<p class="mini">Keep your booking number. Booked for ${escapeHTML(p.holder.firstName+' '+p.holder.lastName)} (${escapeHTML(p.holder.email)}).</p>`;asRenderBookings()}catch(err){el.innerHTML=`<div class="notice warn">${escapeHTML(err.message)}</div><button type="button" class="as-btn" id="asRetryBook">Try confirming again</button>`;$('asRetryBook').onclick=()=>{history.replaceState(null,'',`/?hotelPaid=1&pid=${encodeURIComponent(p.prebookId)}#travel`);asFinishBooking()}}}
function setupTravel(){const today=new Date(),d1=new Date(today.getTime()+14*864e5),d2=new Date(today.getTime()+18*864e5);let saved={};try{saved=JSON.parse(localStorage.getItem('aiva-search-v1')||'{}')}catch{}$('asDepart').min=$('asReturn').min=asIso(today);if(saved.from)$('asFrom').value=saved.from;if(saved.to)$('asTo').value=saved.to;$('asDepart').value=saved.depart>=asIso(today)?saved.depart:asIso(d1);$('asReturn').value=saved.ret&&saved.ret>=$('asDepart').value?saved.ret:asIso(d2);if(saved.pax)$('asPax').value=saved.pax;$('asForm').addEventListener('submit',e=>{e.preventDefault();asSearch()});$('asTabs').addEventListener('click',e=>{const b=e.target.closest('[data-as-tab]');if(b)asTabs(b.dataset.asTab)});$('asFlights').addEventListener('click',e=>{const b=e.target.closest('[data-as-flight]');if(b)asSelectFlight(+b.dataset.asFlight)});$('asHotels').addEventListener('click',e=>{const b=e.target.closest('[data-as-hotel]');if(b)asSelectHotel(+b.dataset.asHotel)});$('asHotelsAll').onclick=()=>{AS.showAll=!AS.showAll;asRenderHotels()};$('asModes').addEventListener('click',e=>{const b=e.target.closest('[data-as-mode]');if(!b)return;if(AS.transfers)asRenderTransfers(b.dataset.asMode);else asStatus('ok','Select a hotel to compare '+AS_MODES[b.dataset.asMode][1].toLowerCase()+' options from the airport.')});$('asReview').addEventListener('click',e=>{if(e.target.closest('[data-as-close]'))$('asReview').hidden=true});$('asReview').addEventListener('submit',e=>{if(e.target.id==='asBookForm'){e.preventDefault();asPay(e.target)}});asTrip();asTabs('all');asRenderBookings();asFinishBooking()}
function setupFinance(){$('fxBase').value='GBP';$('fxTarget').value='USD';$('fxFetch').onclick=async()=>{const base=$('fxBase').value,target=$('fxTarget').value,amount=Number($('fxAmount').value),out=$('fxOutput');if(!Number.isFinite(amount)||amount<0){out.textContent='Enter a valid amount.';return}if(base===target){out.textContent=`${amount} ${base} = ${amount} ${target}`;return}out.textContent='Loading public reference rate…';try{const response=await fetch(`https://api.frankfurter.dev/v1/latest?base=${encodeURIComponent(base)}&symbols=${encodeURIComponent(target)}`,{signal:AbortSignal.timeout(12000)});if(!response.ok)throw new Error('Currency pair unavailable');const data=await response.json(),rate=data.rates?.[target];if(!Number.isFinite(rate))throw new Error('Currency pair unavailable');out.textContent=`${new Intl.NumberFormat('en-GB',{maximumFractionDigits:4}).format(amount)} ${base} ≈ ${new Intl.NumberFormat('en-GB',{maximumFractionDigits:4}).format(amount*rate)} ${target}\n1 ${base} ≈ ${rate} ${target}\nReference date: ${data.date||'not provided'}`}catch(err){out.textContent=`Could not load this rate. ${err.message}. Try GBP, EUR or USD, and check internet access.`}}}
function setupSettings(){$('backup').onclick=()=>{const blob=new Blob([JSON.stringify({app:'Aiva',version:1,exportedAt:new Date().toISOString(),products,suppliers},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='aiva-pocket-hub-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};$('restore').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>2_000_000)throw new Error('Backup exceeds 2 MB');const data=JSON.parse(await file.text());if(!['Aiva','Aiva Pocket Hub'].includes(data.app)||!Array.isArray(data.products)||!Array.isArray(data.suppliers)||data.products.length>3000||data.suppliers.length>3000)throw new Error('Invalid Aiva backup file');if(!confirm('Replace all local products and suppliers with this backup?'))return;const clean=(items,fields)=>items.map(i=>Object.fromEntries(fields.map(f=>[f,String(i?.[f]??'').slice(0,5000)]))).filter(i=>i.id);products=clean(data.products,['id','name','market','category','status','supplier','price']);suppliers=clean(data.suppliers,['id','name','contact','focus','location']);save();renderProducts();renderSuppliers();alert('Backup imported successfully.')}catch(err){alert('Could not import: '+err.message)}finally{e.target.value=''}};$('wipe').onclick=()=>{if(confirm('Permanently delete all locally saved products and suppliers on this device?')){products=[];suppliers=[];save();renderProducts();renderSuppliers()}}}
const EM_EU=['at','be','bg','hr','cy','cz','dk','ee','fi','fr','de','gr','hu','it','lv','lt','lu','mt','nl','pl','pt','ro','sk','si','es','se','is','no','li','ch'];const EM_NUMBERS={gb:[['Police, ambulance, fire','999'],['Also works','112'],['NHS urgent medical advice','111'],['Police non-emergency','101']],ie:[['Emergency services','112'],['Also works','999']],us:[['Emergency services','911']],ca:[['Emergency services','911']],mx:[['Emergency services','911']],au:[['Emergency services','000'],['From mobiles','112']],nz:[['Emergency services','111']],tr:[['Emergency services','112']],in:[['Emergency services','112']],cn:[['Police','110'],['Ambulance','120'],['Fire','119']],jp:[['Police','110'],['Ambulance and fire','119']],ae:[['Police','999'],['Ambulance','998'],['Fire','997']]};EM_EU.forEach(c=>{EM_NUMBERS[c]=EM_NUMBERS[c]||[['Emergency services (EU)','112']]});const em={place:null,cat:'health',seq:0,tseq:0};const emColor=s=>({open:'green',live:'green',ok:'green',closed:'red',none:'red',disrupted:'red'}[s]||'grey');const emDist=m=>m<1000?`${m} m`:`${(m/1000).toFixed(m<10000?1:0)} km`;const emDir=(lat,lon)=>`https://www.google.com/maps/dir/?api=1&destination=${lat},${lon}&travelmode=walking`;const emLink=(url,label,cls='light')=>`<a class="btn ${cls}" href="${escapeHTML(url)}" target="_blank" rel="noopener noreferrer">${label}</a>`;function emStatus(kind,msg){const el=$('emStatus');if(!msg){el.hidden=true;return}el.hidden=false;el.className='voice-status '+kind;el.innerHTML='<span class="dot" aria-hidden="true"></span><span></span>';el.lastChild.textContent=msg}async function emGet(path){const res=await fetch(path,{signal:AbortSignal.timeout(45000)});let data={};try{data=await res.json()}catch{}if(!res.ok)throw new Error(data.error||'Service unavailable. Please try again.');return data}function emRenderWhere(){const p=em.place,nums=EM_NUMBERS[p.countryCode];$('emWhere').hidden=false;$('emWhere').innerHTML=`📍 ${escapeHTML(p.label||'Selected location')}<small>${p.gps?'Your current location':'Searched location'} · ${p.lat.toFixed(4)}, ${p.lon.toFixed(4)}</small>`;const box=$('emNumbers');box.hidden=false;box.innerHTML=(nums?(p.gps?'':'<p class="mini" style="width:100%;margin:0">Numbers for the searched place. Dial them when you are there; your phone calls the network it is on now.</p>')+nums.map((n,i)=>p.gps?`<a class="btn ${i?'light':'call'}" href="tel:${n[1]}">📞 ${n[1]} <span style="font-weight:500">${escapeHTML(n[0])}</span></a>`:`<span class="btn light">☎️ ${n[1]} <span style="font-weight:500">${escapeHTML(n[0])}</span></span>`).join(''):`<div class="item" style="display:flex;gap:10px;align-items:center;padding:6px 0"><i class="em-dot grey"></i><span class="mini">Emergency number for this country is not verified in Aiva. Check official travel advice before you need it.</span></div>${emLink('https://www.gov.uk/foreign-travel-advice','Official travel advice')}`)+(p.gps?'<button class="btn light" type="button" id="emShare">📤 Share my location</button>':'');const share=$('emShare');if(share)share.onclick=async()=>{const url=`https://www.google.com/maps/search/?api=1&query=${p.lat},${p.lon}`;try{if(navigator.share){await navigator.share({title:'My location',text:'This is my current location:',url});return}await navigator.clipboard.writeText(url);emStatus('ok','Location link copied. Paste it into a message to a trusted contact.')}catch(err){if(err?.name!=='AbortError')emStatus('error','Could not share automatically. Location link: '+url)}}}async function emSetPlace(place){em.place=place;emRenderWhere();emStatus('',null);$('emTransportRefresh').disabled=false;emLoadTransport();emLoadPlaces()}function emLocate(){if(!navigator.geolocation){emStatus('error','Location is not available in this browser. Search for a place instead.');return}emStatus('busy','Finding your location…');navigator.geolocation.getCurrentPosition(async pos=>{const lat=pos.coords.latitude,lon=pos.coords.longitude;let info={label:'',countryCode:''};try{info=await emGet(`/api/emergency/geocode?lat=${lat}&lon=${lon}`)}catch{}emSetPlace({lat,lon,label:info.label||'Your location',countryCode:info.countryCode||'',gps:true})},err=>emStatus('error',err.code===1?'Location access is blocked. Allow location for Aiva in your browser settings, or search for a place instead.':'Your location could not be found. Search for a place instead.'),{enableHighAccuracy:true,timeout:15000,maximumAge:60000})}async function emSearch(){const q=$('emQuery').value.trim();if(!q){emStatus('error','Type a town, street or postcode, or tap Use my location.');return}emStatus('busy','Searching…');try{const r=await emGet('/api/emergency/geocode?q='+encodeURIComponent(q));emSetPlace({...r,gps:false})}catch(err){emStatus('error',err.message)}}function emQS(){const p=em.place;return `lat=${p.lat}&lon=${p.lon}&cc=${encodeURIComponent(p.countryCode||'')}&gps=${p.gps?1:0}&tz=${encodeURIComponent(Intl.DateTimeFormat().resolvedOptions().timeZone||'')}`}async function emLoadTransport(){if(!em.place)return;const seq=++em.tseq,box=$('emTransport');box.innerHTML='<div class="empty">Loading live transport…</div>';$('emTransportSource').textContent='';try{const d=await emGet('/api/emergency/transport?'+emQS());if(seq!==em.tseq)return;box.innerHTML=d.stops.length?d.stops.map(emStopHTML).join(''):'<div class="empty">No stations or stops found within 1 km.</div>';$('emTransportSource').textContent=`${d.live?'Live data':'Station and stop locations'}: ${d.source} · updated ${new Date(d.retrieved).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit',second:'2-digit'})}`+(d.live?'':' · Live times are not available in Aiva for this area yet. Use the official links for live times.')}catch(err){if(seq===em.tseq)box.innerHTML=`<div class="item"><i class="em-dot grey"></i><div class="em-body">${escapeHTML(err.message)}</div></div>`}}function emStopHTML(s){const c=emColor(s.state),modes={bus:'🚌',tube:'🚇',tram:'🚊',dlr:'🚈',overground:'🚆','elizabeth-line':'🚆','national-rail':'🚆',train:'🚆',ferry:'⛴️'};const deps=s.departures.length?`<ul class="em-deps">${s.departures.slice(0,5).map(d=>`<li><span><b>${escapeHTML(d.line)}</b> → ${escapeHTML(d.destination)}${d.platform?` <span class="mini">· ${escapeHTML(d.platform)}</span>`:''}${d.status?` <span class="mini ${d.cancelled?'em-state red':''}">· ${escapeHTML(d.status)}</span>`:''}${d.realtime===false?' <span class="mini">· timetabled</span>':''}</span><b class="${d.cancelled?'em-state red':''}">${d.cancelled?'Cancelled':d.unknownTime?(/^Delayed/.test(d.status)?'Delayed':'No estimate'):d.minutes?d.minutes+' min':'Due'}</b></li>`).join('')}</ul>`:'';const lines=s.lines.length?`<div class="em-lines">${s.lines.map(l=>`<button type="button" class="em-line" ${s.timetable?`data-em-tt="${escapeHTML(l.id)}" data-em-stop="${escapeHTML(s.id)}" title="Show first and last services"`:''}><i class="em-dot ${emColor(l.state)}"></i>${escapeHTML(l.name)} · ${escapeHTML(l.status)}</button>`).join('')}</div>`:'';const reasons=[...new Set([...s.lines.filter(l=>l.reason&&l.state!=='ok').map(l=>l.reason),...(s.alerts||[])])].slice(0,2).map(r=>`<div class="em-reason">⚠️ ${escapeHTML(r)}</div>`).join('');return `<div class="item"><i class="em-dot ${c}"></i><div class="em-body"><div class="item-title">${(s.modes.map(m=>modes[m]).find(Boolean))||'🚏'} ${escapeHTML(s.name)}${s.indicator?` <span class="mini">${escapeHTML(s.indicator)}</span>`:''}</div><div class="mini">${emDist(s.distance)} away</div><div class="em-state ${c}">${escapeHTML(s.label)}</div>${deps}${lines}${reasons}${s.timetable?'<div class="em-tt" data-em-ttout></div>':''}<div class="em-links">${emLink(emDir(s.lat,s.lon),'🧭 Directions')}${(s.links||[]).map(l=>emLink(l.url,escapeHTML(l.label))).join('')}</div></div></div>`}async function emTimetable(btn){const out=btn.closest('.em-body').querySelector('[data-em-ttout]');if(!out)return;out.textContent='Loading today\'s first and last services…';try{const d=await emGet(`/api/emergency/timetable?line=${encodeURIComponent(btn.dataset.emTt)}&stop=${encodeURIComponent(btn.dataset.emStop)}`);out.innerHTML=d.directions.map(x=>`<div>🕐 <b>${escapeHTML(d.line.toUpperCase())}</b>${x.towards?' '+escapeHTML(x.towards):''}: ${x.schedule?(x.runs24h?'<b>Runs 24 hours today</b>':`first ${escapeHTML(x.first)} · last ${escapeHTML(x.last)}`)+` <span>(${escapeHTML(x.schedule)} timetable)</span>`:'no timetable published for today'}</div>`).join('')+'<div>Scheduled times from TfL; check live departures above for changes.</div>'}catch(err){out.textContent=err.message}}function emBookingURL(p){const day=n=>{const d=new Date();d.setDate(d.getDate()+n);return d.toLocaleDateString('en-CA')};return `https://www.booking.com/searchresults.html?ss=${encodeURIComponent([p.name,p.city].filter(Boolean).join(', '))}&checkin=${day(0)}&checkout=${day(1)}&group_adults=1&no_rooms=1`}function emPlaceHTML(p){const c=emColor(p.status.state),stay=em.cat==='stay'&&p.kind!=='Emergency shelter';const links=[emLink(emDir(p.lat,p.lon),'🧭 Directions')];if(p.phone)links.push(emLink('tel:'+p.phone.split(/[;,]/)[0].replace(/[^\d+]/g,''),'📞 Call'));if(stay)links.push(emLink(emBookingURL(p),'Check price &amp; availability'));if(p.website&&/^https?:\/\//.test(p.website))links.push(emLink(p.website,'Website'));return `<div class="item"><i class="em-dot ${c}"></i><div class="em-body"><div class="item-title">${escapeHTML(p.name)}</div><div class="mini">${escapeHTML(p.kind)}${p.emergency?' · <b style="color:#b42335">Emergency department (A&amp;E) listed</b>':''} · ${emDist(p.distance)} away${p.address?' · '+escapeHTML(p.address):''}</div><div class="em-state ${c}">${escapeHTML(p.status.label)}</div>${p.openingHours&&p.status.state!=='unknown'?`<div class="mini">Listed hours: ${escapeHTML(p.openingHours)}${p.checked?` · checked ${escapeHTML(p.checked)}`:''}</div>`:''}${stay?'<div class="mini">Price and availability: not verified in Aiva</div>':''}<div class="em-links">${links.join('')}</div></div></div>`}async function emLoadPlaces(){if(!em.place)return;const seq=++em.seq,box=$('emPlaces');$('emStay').hidden=em.cat!=='stay';box.innerHTML='<div class="empty">Loading nearby services…</div>';$('emPlacesSource').textContent='';try{const d=await emGet(`/api/emergency/places?${emQS()}&category=${em.cat}&radius=${$('emRadius').value}`);if(seq!==em.seq)return;let extra='';if(em.cat==='stay'&&em.place.countryCode==='gb')extra=`<div class="item"><i class="em-dot grey"></i><div class="em-body"><div class="item-title">Homeless or at risk tonight (UK)</div><div class="mini">Your local council must help with emergency housing. Shelter's free helpline gives urgent advice.</div><div class="em-links">${emLink('https://www.gov.uk/find-local-council','Find your local council')}${emLink('tel:08088004444','📞 Shelter 0808 800 4444')}</div></div></div>`;box.innerHTML=extra+(d.places.length?d.places.map(emPlaceHTML).join(''):'<div class="empty">Nothing of this type is listed nearby. Try a larger search distance.</div>');$('emPlacesSource').textContent=`Source: ${d.source} · ${d.localTimeKnown?'open/closed shown in local time ('+d.timeZone+')':'local time zone unknown, so open/closed is not verified'} · updated ${new Date(d.retrieved).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}`}catch(err){if(seq===em.seq)box.innerHTML=`<div class="item"><i class="em-dot grey"></i><div class="em-body">${escapeHTML(err.message)}</div></div>`}}function setupEmergency(){$('emLocate').onclick=emLocate;$('emSearch').onclick=emSearch;$('emQuery').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();emSearch()}});$('emRadius').onchange=emLoadPlaces;$('emTransportRefresh').onclick=emLoadTransport;document.querySelectorAll('[data-em-cat]').forEach(b=>b.onclick=()=>{em.cat=b.dataset.emCat;document.querySelectorAll('[data-em-cat]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-selected',String(x===b))});emLoadPlaces()});$('emTransport').addEventListener('click',e=>{const b=e.target.closest('[data-em-tt]');if(b)emTimetable(b)})}setupNav();setupTrade();setupTranslation();setupCalculator();setupTravel();setupFinance();setupSettings();setupEmergency();$('year').textContent=new Date().getFullYear();if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./service-worker.js').catch(()=>{}));
